CREATE VIEW [dbo].[PRINT_FORMULA]
 AS 
SELECT     dbo.HEAD_MANF.FNUMB AS FNUMB1, dbo.HEAD_MANF.CODE AS COKAL, dbo.HEAD_MANF.DATE_ACTIV, dbo.HEAD_MANF.IMBIBE_MANF, dbo.HEAD_MANF.IMBIBE_SAR, dbo.HEAD_MANF.GHEYMAT, dbo.HEAD_MANF.NAMES, dbo.HEAD_MANF.N_KOL, dbo.HEAD_MANF.NUMBER, dbo.HEAD_MANF.TNUMBER, dbo.DTL_MANF.FNUMB, dbo.DTL_MANF.CODE AS COMAVAD, dbo.DTL_MANF.ANBAR, dbo.DTL_MANF.VAHED_K, dbo.DTL_MANF.MEGH, dbo.DTL_MANF.MEGHk, dbo.DTL_MANF.PERT, dbo.DTL_MANF.SMABL, dbo.DTL_MANF.MABLK, dbo.STUF_DEF.NAME AS KALA,STUF_DEF_1.NAME + ' ' + dbo.DTL_MANF.CODE AS MAVAD, dbo.HEAD_MANF.SA_HOUR  FROM   dbo.STUF_DEF INNER JOIN  dbo.HEAD_MANF ON dbo.STUF_DEF.CODE = dbo.HEAD_MANF.CODE INNER JOIN   dbo.TCOD_VAHEDS INNER JOIN  dbo.DTL_MANF INNER JOIN  dbo.STUF_DEF STUF_DEF_1 ON dbo.DTL_MANF.CODE = STUF_DEF_1.CODE ON dbo.TCOD_VAHEDS.CODE = dbo.DTL_MANF.VAHED_K ON  dbo.HEAD_MANF.FNUMB = dbo.DTL_MANF.FNUMB WHERE (dbo.HEAD_MANF.NAMES Is Null)
